function App() {
  const items = Array.from({ length: 5000 }, (_, i) => `Row #${i}`);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Rendering all {items.length} rows as real DOM nodes.</p>
      <div style={{ height: 240, overflow: 'auto', border: '1px solid #ccc' }}>
        {items.map((label, i) => (
          <div key={i} style={{ height: 32, padding: '6px 10px', borderBottom: '1px solid #eee' }}>{label}</div>
        ))}
      </div>
    </div>
