function App() {
  const ROW = 32;
  const HEIGHT = 240;
  const OVERSCAN = 3;
  const total = 5000;
  const [scrollTop, setScrollTop] = useState(0);
  const start = Math.max(0, Math.floor(scrollTop / ROW) - OVERSCAN);
  const end = Math.min(total, Math.ceil((scrollTop + HEIGHT) / ROW) + OVERSCAN);
  const rows = [];
  for (let i = start; i < end; i++) rows.push(i);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Mounting rows {start}–{end} of {total} ({rows.length} DOM nodes).</p>
      <div
        onScroll={e => setScrollTop(e.currentTarget.scrollTop)}
        style={{ height: HEIGHT, overflow: 'auto', border: '1px solid #ccc', position: 'relative' }}
      >
        <div style={{ height: total * ROW, position: 'relative' }}>
          {rows.map(i => (
            <div key={i} style={{ position: 'absolute', top: i * ROW, height: ROW, width: '100%', padding: '6px 10px', borderBottom: '1px solid #eee', boxSizing: 'border-box' }}>Row #{i}</div>
          ))}
        </div>
      </div>
    </div>
  );
}

